def class_record(bottles):
    total = 0
    low = bottles[0]
    for b in bottles:
        total += b
        if b < low:
            low = b
    return (total - low) // (len(bottles) - 1)


def solution(classes):
    records = []
    for c in classes:
        records.append(class_record(c))
    total = 0
    high = records[0]
    low = records[0]
    for r in records:
        total += r
        if r > high:
            high = r
        if r < low:
            low = r
    answer = (total - high - low) // (len(records) - 2)
    return answer

