def team_record(times, limit):
    total = 0
    count = 0
    fast = 201
    slow = 0
    for t in times:
        if t <= limit:
            total += t
            count += 1
            if t < fast:
                fast = t
            if t > slow:
                slow = t
    if count >= 3:
        return [(total - fast - slow) // (count - 2), count]
    if count >= 1:
        return [total // count, count]
    return [0, 0]


def solution(teams, limit):
    answer = -1
    best_rec = 0
    best_cnt = 0
    for i in range(len(teams)):
        result = team_record(teams[i], limit)
        rec = result[0]
        cnt = result[1]
        if cnt == 0:
            continue
        if answer == -1 or rec < best_rec or (rec == best_rec and cnt > best_cnt):
            answer = i + 1
            best_rec = rec
            best_cnt = cnt
    return answer

